/* Editable course-purpose and objective editor. Kept as a small enhancement layer so the
   official outline renderer remains compatible with the existing prototype modules. */
(function(){
  const key='ai-jiaowu-syllabus-objectives-v1', purposeKey='ai-jiaowu-syllabus-purpose-v1';
  const esc=value=>String(value==null?'':value).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const defaults=[
    {name:'课程目标 1',content:'能阐明典型离散的基本数据结构，能够理解集合论、命题逻辑、谓词逻辑、图论与群环域等基本概念，并能够演算和分析典型图论算法等。',weight:'0.4',support:'1.3、1.6'},
    {name:'课程目标 2',content:'针对复杂工程问题，运用离散数学结构开展逻辑建模、方案分析和优劣评估。',weight:'0.3',support:'2.3'},
    {name:'课程目标 3',content:'检索离散数学结构领域资料，开展自主学习、完成学习报告并提出问题。',weight:'0.3',support:'4.1'}
  ];
  const read=()=>{try{const v=JSON.parse(localStorage.getItem(key)||'null');return Array.isArray(v)&&v.length?v:defaults.map(x=>({...x}));}catch{return defaults.map(x=>({...x}));}};
  const purpose=()=>{try{return localStorage.getItem(purposeKey)||'本课程旨在培养学生运用离散数学基本理论和方法分析、解决复杂问题的能力，形成严谨的逻辑思维与自主学习意识。';}catch{return '';}};
  const editor=()=>{const data=read();return '<div class="syllabus-objective-editor"><label class="syllabus-purpose-field"><span>课程目的</span><textarea id="syllabusPurpose" rows="3">'+esc(purpose())+'</textarea></label><div class="syllabus-objective-setting-head"><div><b>课程目标设定</b><small>目标编号自动累加，名称和内容均可自主修改</small></div><button type="button" class="btn secondary" data-objective-add>＋ 新增课程目标</button></div><div class="syllabus-objective-list">'+data.map((x,i)=>'<article class="syllabus-objective-card" data-objective-index="'+i+'"><div class="syllabus-objective-card-head"><span class="official-section-number">'+String(i+1).padStart(2,'0')+'</span><input class="syllabus-objective-name" aria-label="课程目标名称" value="'+esc(x.name||('课程目标 '+(i+1)))+'"><button type="button" class="icon-btn syllabus-objective-remove" data-objective-remove>删除</button></div><label class="syllabus-objective-field"><span>课程目标内容</span><textarea class="syllabus-objective-content" rows="3">'+esc(x.content||'')+'</textarea></label></article>').join('')+'</div><div class="syllabus-objective-actions"><button type="button" class="btn primary" data-objective-save>保存课程目标</button><span class="syllabus-save-state" aria-live="polite"></span></div></div>';};
  const table=()=>'<div class="official-table-wrap"><table class="official-table"><thead><tr><th>课程目标</th><th>权重</th><th>支撑指标点</th><th>目标描述</th></tr></thead><tbody>'+read().map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.weight)+'</td><td>'+esc(x.support)+'</td><td>'+esc(x.content)+'</td></tr>').join('')+'</tbody></table></div>';
  const mount=()=>{if(location.hash!=='#course/syllabus')return;const outline=document.querySelector('.official-outline');if(!outline)return;const sections=[...outline.querySelectorAll('.official-section')];const target=sections.find(s=>s.querySelector('.official-section-number')?.textContent.trim()==='03');if(!target||target.dataset.objectiveEditor)return;target.dataset.objectiveEditor='1';target.classList.add('official-wide');const title=target.querySelector('summary b'), sub=target.querySelector('summary small'), body=target.querySelector('.official-section-body');if(title)title.textContent='课程目标编辑';if(sub)sub.textContent='课程内容编辑与课程目标设定';if(body)body.innerHTML=editor();const support=sections.find(s=>s.querySelector('.official-section-number')?.textContent.trim()==='04');if(support){const b=support.querySelector('.official-section-body');if(b){b.dataset.objectiveTable='1';b.innerHTML=table();}}};
  document.addEventListener('click',e=>{if(location.hash!=='#course/syllabus')return;const add=e.target.closest('[data-objective-add]');if(add){const list=add.closest('.syllabus-objective-editor').querySelector('.syllabus-objective-list'), i=list.children.length;list.insertAdjacentHTML('beforeend','<article class="syllabus-objective-card" data-objective-index="'+i+'"><div class="syllabus-objective-card-head"><span class="official-section-number">'+String(i+1).padStart(2,'0')+'</span><input class="syllabus-objective-name" aria-label="课程目标名称" value="课程目标 '+(i+1)+'"><button type="button" class="icon-btn syllabus-objective-remove" data-objective-remove>删除</button></div><label class="syllabus-objective-field"><span>课程目标内容</span><textarea class="syllabus-objective-content" rows="3"></textarea></label></article>');return;}const remove=e.target.closest('[data-objective-remove]');if(remove){const list=remove.closest('.syllabus-objective-list');if(list.children.length<=1)return;remove.closest('.syllabus-objective-card').remove();[...list.children].forEach((card,i)=>{card.dataset.objectiveIndex=i;card.querySelector('.official-section-number').textContent=String(i+1).padStart(2,'0');});return;}const save=e.target.closest('[data-objective-save]');if(save){const root=save.closest('.syllabus-objective-editor'), data=[...root.querySelectorAll('.syllabus-objective-card')].map((card,i)=>({name:card.querySelector('.syllabus-objective-name').value.trim()||('课程目标 '+(i+1)),content:card.querySelector('.syllabus-objective-content').value.trim(),weight:read()[i]?.weight||'',support:read()[i]?.support||''}));try{localStorage.setItem(key,JSON.stringify(data));localStorage.setItem(purposeKey,root.querySelector('#syllabusPurpose').value.trim());}catch{}const state=root.querySelector('.syllabus-save-state');if(state){state.textContent='已保存';setTimeout(()=>state.textContent='',1800);}const b=document.querySelector('[data-objective-table]');if(b)b.innerHTML=table();}});
  window.addEventListener('hashchange',()=>setTimeout(mount,0));
  if(window.MutationObserver){const observer=new MutationObserver(mount);observer.observe(document.body,{childList:true,subtree:true});}
  setTimeout(mount,0);
})();

